import { NextFunction, Request, Response, Router } from "express";
import { AdvanceOrderUseCase } from "../application/advance-order-use-case";
import { CancelOrderUseCase } from "../application/cancel-order-use-case";
import { GetOrderUseCase } from "../application/get-order-use-case";
import { ListOrdersByStateUseCase } from "../application/list-orders-by-state-use-case";
import { PlaceOrderUseCase } from "../application/place-order-use-case";

type Handler = (req: Request, res: Response) => Promise<void>;

function wrap(handler: Handler) {
  return (req: Request, res: Response, next: NextFunction): void => {
    handler(req, res).catch(next);
  };
}

export class OrderController {
  constructor(
    private readonly placeOrder: PlaceOrderUseCase,
    private readonly advanceOrder: AdvanceOrderUseCase,
    private readonly cancelOrder: CancelOrderUseCase,
    private readonly getOrder: GetOrderUseCase,
    private readonly listByState: ListOrdersByStateUseCase,
  ) {}

  routes(): Router {
    const router = Router();
    router.post("/", wrap((req, res) => this.place(req, res)));
    router.get("/", wrap((req, res) => this.list(req, res)));
    router.get("/:id", wrap((req, res) => this.get(req, res)));
    router.post("/:id/advance", wrap((req, res) => this.advance(req, res)));
    router.post("/:id/cancel", wrap((req, res) => this.cancel(req, res)));
    return router;
  }

  private async place(req: Request, res: Response): Promise<void> {
    const body = (req.body ?? {}) as { customerId?: unknown; items?: unknown };
    const order = await this.placeOrder.execute({ customerId: body.customerId, items: body.items });
    res.status(201).json(order);
  }

  private async list(req: Request, res: Response): Promise<void> {
    res.json(await this.listByState.execute(req.query.state));
  }

  private async get(req: Request, res: Response): Promise<void> {
    res.json(await this.getOrder.execute(String(req.params.id)));
  }

  private async advance(req: Request, res: Response): Promise<void> {
    res.json(await this.advanceOrder.execute(String(req.params.id)));
  }

  private async cancel(req: Request, res: Response): Promise<void> {
    res.json(await this.cancelOrder.execute(String(req.params.id)));
  }
}

