import { NextFunction, Request, Response, Router } from "express";
import { ListStockLevelsUseCase } from "../application/list-stock-levels-use-case";

export class StockController {
  constructor(private readonly listStock: ListStockLevelsUseCase) {}

  routes(): Router {
    const router = Router();
    router.get("/", (_req: Request, res: Response, next: NextFunction) => {
      this.listStock.execute().then((levels) => res.json(levels), next);
    });
    return router;
  }
}

